CREATE DATABASE IF NOT EXISTS rk_db;

CREATE TABLE IF NOT EXISTS rk_db.raw_census AS
SELECT *
FROM file('/var/lib/clickhouse/user_files/import/data.parquet', 'Parquet');

CREATE TABLE rk_db.census_analytics
(
    object_level String,
    region String,
    settlement String,
    latitude Float64,
    longitude Float64,
    nationality String,
    population Int32
)
ENGINE = MergeTree
ORDER BY (region, nationality);

INSERT INTO rk_db.census_analytics
SELECT
    object_level,
    region,
    settlement,
    ifNull(latitude_dadata, 0.0) AS latitude,
    ifNull(longitude_dadata, 0.0) AS longitude,
    nationality,
    toInt32(population) AS population
FROM (
         SELECT
             object_level,
             region,
             settlement,
             latitude_dadata,
             longitude_dadata,
             ['Абазины', 'Абхазы', 'Аварцы', 'Андийцы', 'Арчинцы', 'Ахвахцы', 'Багулалы', 'Бежтинцы', 'Ботлихцы', 'Гинухцы', 'Годоберинцы', 'Гунзибцы', 'Дидойцы', 'Каратинцы', 'Тиндалы', 'Хваршины', 'Чамалалы', 'Агулы (агульцы)', 'Адыгейцы (абадзехи, адыгейцы-черкесы, адыги, адыгэ, сирийские адыгейцы, адыги-черкесы, черкесы-бжедуги)', 'Азербайджанцы (азер)', 'Алеуты', 'Алтайцы', 'Теленгиты', 'Тубалары', 'Челканцы', 'Американцы (афроамериканцы)', 'Арабы (алжирцы, египтяне, иорданцы, иракцы, йеменцы, катарцы, ливанцы, ливийцы, марокканцы, палестинцы, сирийцы)', 'Армяне (русские армяне)', 'Черкесогаи', 'Ассирийцы', 'Афганцы (афганистанцы, пуштуны, хазарейцы)', 'Балкарцы', 'Башкиры', 'Белорусы (беларусы)', 'Бесермяне', 'Болгары', 'Боснийцы', 'Британцы (англичане)', 'Буряты', 'Венгры', 'Вепсы', 'Водь', 'Вьетнамцы', 'Гагаузы', 'Горские евреи', 'Греки (византийскийские греки, рум)', 'Греки-урумы', 'Грузинские евреи', 'Грузины', 'Аджарцы', 'Ингилойцы', 'Лазы', 'Мегрелы (менгрелы, мингрелы)', 'Сваны', 'Даргинцы', 'Кайтагцы', 'Кубачинцы', 'Долганы', 'Дунгане', 'Евреи', 'Езиды', 'Ижорцы', 'Ингуши', 'Индийцы (индуисты)', 'Испанцы', 'Итальянцы', 'Ительмены', 'Кабардинцы (адыги (с языком кабардинским))', 'Казахи', 'Калмыки', 'Камчадалы', 'Караимы', 'Каракалпаки', 'Карачаевцы (карачаево-черкесы, карачай)', 'Карелы', 'Кереки', 'Кеты (остяки)', 'Юги', 'Киргизы (кыргыз)', 'Китайцы', 'Коми (коми-зыряне)', 'Коми-ижемцы', 'Коми-пермяки (пермяки)', 'Корейцы', 'Коряки', 'Алюторцы', 'Крымские татары', 'Крымчаки', 'Кубинцы', 'Кумандинцы', 'Кумыки', 'Курды (курд)', 'Курманч', 'Лакцы (кулинцы, лаки)', 'Латыши (курляндцы)', 'Латгальцы', 'Лезгины', 'Литовцы', 'Македонцы', 'Манси', 'Марийцы (мари, марий)', 'Горные марийцы', 'Лугово-восточные марийцы', 'Молдаване', 'Монголы', 'Мордва (мордвины, мордовцы)', 'Мордва-мокша', 'Мордва-эрзя (эрзя)', 'Нагайбаки', 'Нанайцы', 'Нганасаны', 'Негидальцы', 'Немцы (русские немцы)', 'Меннониты', 'Ненцы', 'Нивхи', 'Ногайцы', 'Карагаши', 'Орочи', 'Осетины (аланы)